<script setup>
import {ref,onMounted} from 'vue';import {useRecords,api} from '../stores/records.js';import {useFeedback} from '../stores/feedback.js';import Feedback from '../components/Feedback.vue';import RecordTable from '../components/RecordTable.vue';const store=useRecords();const {busy,error,success,run}=useFeedback();const studentId=ref(''),courseId=ref(''),rosterId=ref(''),roster=ref([]);const columns=[{key:'name',label:'Name'},{key:'id',label:'Student ID'},{key:'phone',label:'Phone'},{key:'zip',label:'ZIP code'}];onMounted(()=>run(async()=>{await Promise.all([store.loadStudents(),store.loadCourses()]);}));async function refresh(){roster.value=rosterId.value?await api('/courses/'+encodeURIComponent(rosterId.value)+'/students'):[];}function enroll(){run(async()=>{await api('/enrollments','POST',{studentId:studentId.value,courseId:courseId.value});rosterId.value=courseId.value;await refresh();studentId.value='';},'Enrollment created successfully.');}function loadRoster(){run(async()=>{roster.value=[];await refresh();});}
</script>
<template><div class="heading"><p class="eyebrow">REGISTRATION</p><h1>Enrollments</h1><p>Register students for courses and view course rosters.</p></div><Feedback :busy="busy" :error="error" :success="success"/><div class="layout"><section class="panel"><h2>New enrollment</h2><p v-if="!busy&&(!store.students.length||!store.courses.length)" class="empty">Add at least one student and course before enrolling.</p><form @submit.prevent="enroll"><label for="student">Student</label><select id="student" v-model="studentId" required :disabled="busy"><option disabled value="">Choose a student</option><option v-for="s in store.students" :key="s.id" :value="s.id">{{s.name}} ({{s.id}})</option></select><label for="course">Course</label><select id="course" v-model="courseId" required :disabled="busy"><option disabled value="">Choose a course</option><option v-for="c in store.courses" :key="c.id" :value="c.id">{{c.id}} — {{c.name}}</option></select><button :disabled="busy||!store.students.length||!store.courses.length">Enroll student</button></form></section><section class="panel"><h2>Course roster</h2><label for="roster">Select a course</label><select id="roster" v-model="rosterId" :disabled="busy" @change="loadRoster"><option value="">Choose a course</option><option v-for="c in store.courses" :key="c.id" :value="c.id">{{c.id}} — {{c.name}}</option></select><RecordTable :rows="roster" :columns="columns" :busy="busy" :empty="rosterId?'No students enrolled in this course.':'Select a course to see its students.'"/></section></div></template>
